public List<Integer> freqQuery(int[][] queries) {
    Map<Integer, Integer> valueCount = new HashMap<>();
    List<Integer> out = new ArrayList<>();
    for (int[] q : queries) {
        int type = q[0], x = q[1];
        if (type == 1) {
            valueCount.merge(x, 1, Integer::sum);
        } else if (type == 2) {
            valueCount.computeIfPresent(x, (k, v) -> v > 1 ? v - 1 : null);
        } else {
            boolean found = valueCount.containsValue(x);
            out.add(found ? 1 : 0);
        }
    }
    return out;
}

