public List<Integer> freqQuery(int[][] queries) {
    Map<Integer, Integer> valueCount = new HashMap<>();
    Map<Integer, Integer> freqOfFreq = new HashMap<>();
    List<Integer> out = new ArrayList<>();
    for (int[] q : queries) {
        int type = q[0], x = q[1];
        if (type == 1) {
            int f = valueCount.getOrDefault(x, 0);
            if (f > 0) freqOfFreq.merge(f, -1, Integer::sum);
            valueCount.put(x, f + 1);
            freqOfFreq.merge(f + 1, 1, Integer::sum);
        } else if (type == 2) {
            int f = valueCount.getOrDefault(x, 0);
            if (f > 0) {
                freqOfFreq.merge(f, -1, Integer::sum);
                valueCount.put(x, f - 1);
                if (f - 1 > 0) freqOfFreq.merge(f - 1, 1, Integer::sum);
            }
        } else {
            out.add(freqOfFreq.getOrDefault(x, 0) > 0 ? 1 : 0);
        }
    }
    return out;
}

