    value_count: dict[int, int] = {}
    freq_of_freq: dict[int, int] = {}
    out: list[int] = []
    for type_, x in queries:
        if type_ == 1:
            f = value_count.get(x, 0)
            if f > 0:
                freq_of_freq[f] -= 1
            value_count[x] = f + 1
            freq_of_freq[f + 1] = freq_of_freq.get(f + 1, 0) + 1
        elif type_ == 2:
            f = value_count.get(x, 0)
            if f > 0:
                freq_of_freq[f] -= 1
                value_count[x] = f - 1
                if f - 1 > 0:
                    freq_of_freq[f - 1] = freq_of_freq.get(f - 1, 0) + 1
        else:
            out.append(1 if freq_of_freq.get(x, 0) > 0 else 0)
    return out

